/* llm-entity-extraction — experiment log viewer.
 * Dependency-free, hash-routed, data files under ./data/ generated by
 * scripts/site/build_site.py.
 *
 * Views:
 *   #/                          index: stats + scoring reference + runs table
 *   #/task/{slug}               task view: aggregates + runs, grouped by prompt
 *   #/prompt/{prompt}           prompt view: all runs of a prompt version,
 *                               grouped by task
 *   #/model/{model}             model view (same template)
 *   #/run/{id}                  run detail: headline cards, score composition,
 *                               per-document results
 *   #/run/{id}/doc/{i}          single-document trace: classification +
 *                               full extraction scores, interpreted
 *
 * Sample-size awareness: every headline score carries a Wilson 95% CI whose
 * width shrinks with n (n=5 -> ±27pp, n=509 -> ±2.2pp), and the "Δ vs best"
 * column is only colored when the difference is statistically significant
 * (two-proportion z-test) — small-sample runs are never "overly punished".
 */
"use strict";

const state = { meta: null, index: [], sortKey: "id", sortDir: "desc" };

const $ = (sel) => document.querySelector(sel);

function esc(v) {
  return String(v ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

const fmt = {
  int: (n) => (n == null ? "—" : Number(n).toLocaleString("en-US")),
  pct: (v) => (v == null ? "—" : `${(v * 100).toFixed(1)}%`),
  score: (v) => (v == null ? "—" : v.toFixed(4)),
  date: (iso) => {
    if (!iso) return "—";
    const d = new Date(iso);
    return isNaN(d) ? iso : d.toISOString().replace("T", " ").slice(0, 16) + " UTC";
  },
  tokens: (v) => (v == null ? "—" : Number(v).toLocaleString("en-US")),
};

/* ---------- statistics (sample-size-aware) ---------- */

function wilsonHalf(p, n, z = 1.96) {
  if (p == null || !n) return null;
  const denom = 1 + z * z / n;
  const center = (p + z * z / (2 * n)) / denom;
  return z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n)) / denom;
}

function pooledSEpp(runA, runB) {
  const p1 = runA.headline?.value, p2 = runB.headline?.value;
  const n1 = runA.n_rows, n2 = runB.n_rows;
  if (p1 == null || p2 == null || !n1 || !n2) return null;
  return 100 * Math.sqrt((p1 * (1 - p1)) / n1 + (p2 * (1 - p2)) / n2);
}

function ciText(run) {
  const ci = run.ci95;
  if (!ci) return "";
  const n = run.n_rows;
  const src = ci.source === "wilson" ? "Wilson 95% interval" : "bootstrap 95% CI (percentile, 2000 resamples)";
  return `<span class="hl-sample faint mono" title="${esc(src)} — width shrinks with sample size">` +
    `n=${fmt.int(n)} · 95% CI ${(ci.lo * 100).toFixed(1)}–${(ci.hi * 100).toFixed(1)}%</span>`;
}

/* ---------- display bands (documented in the scoring card) ---------- */

function band(v) {
  if (v == null) return null;
  if (v >= 0.85) return { cls: "good", label: "Strong" };
  if (v >= 0.6) return { cls: "warn", label: "Moderate" };
  return { cls: "bad", label: "Weak" };
}

function bandChip(v, label) {
  const b = band(v);
  if (!b) return "";
  return `<span class="chip ${b.cls}" title="display band — see the scoring card">${esc(label || b.label)}</span>`;
}

function barHtml(v) {
  if (v == null) return '<span class="faint">—</span>';
  const pct = Math.max(0, Math.min(1, v)) * 100;
  return `<span class="bar ${band(v).cls}"><i style="width:${pct.toFixed(1)}%"></i></span>`;
}

function taskTag(task, asLink = false) {
  const label = (task || "").replace("_", " ");
  const cls = task?.startsWith("contract")
    ? "extraction"
    : task?.startsWith("chained")
      ? "chained"
      : task?.startsWith("subtype")
        ? "subtype"
        : "";
  const inner = esc(label);
  const html = `<span class="task-tag ${cls}">${inner}</span>`;
  if (!asLink) return html;
  return `<a href="#/task/${encodeURIComponent(task || "")}" data-nav-stop>${html}</a>`;
}

/* Headline cell: big %, CI + n, band, bar, label, composition. */
function headlineCell(h, run) {
  if (!h || h.value == null) return '<span class="faint">—</span>';
  const b = band(h.value);
  const pct = (h.value * 100).toFixed(1);
  return `<span class="hl" title="${esc(h.label || "")}: ${pct}% (${esc(h.detail || "")})">
    <span class="hl-row">
      <strong class="hl-val ${b ? b.cls : ""}">${pct}%</strong>
      <span class="hl-raw faint mono">${fmt.score(h.value)}</span>
      <span class="hl-bar">${barHtml(h.value)}</span>
      ${b ? `<span class="chip ${b.cls}">${b.label}</span>` : ""}
    </span>
    ${run ? ciText(run) : ""}
    <span class="hl-label soft">${esc(h.label || "")}</span>
    ${h.detail ? `<span class="hl-detail faint">${esc(h.detail)}</span>` : ""}
  </span>`;
}

/* Δ vs best — colored only when statistically significant at 95% AND the two
 * runs share the same evaluation surface (dataset fingerprint + seed + sample
 * size). The backend already computes delta_best_pp against the same-surface
 * best; this cell additionally refuses to color across different surfaces. */
function deltaCell(run, bestRun) {
  if (run.delta_best_pp == null) {
    if (bestRun && run.sample_key && run.sample_key !== bestRun.sample_key) {
      return `<span class="delta ns" title="No same-surface comparison: this run's sample (${esc(run.sample_key)}) differs from the best run's (${esc(bestRun.sample_key)}). Deltas across different samples are not meaningful.">≈ Δ surface</span>`;
    }
    return '<span class="faint">—</span>';
  }
  if (run.delta_best_pp === 0) return '<span class="delta zero">best</span>';
  const se = bestRun && bestRun.sample_key === run.sample_key ? pooledSEpp(run, bestRun) : null;
  const d = run.delta_best_pp;
  const label = `${d > 0 ? "+" : ""}${d.toFixed(1)}pp`;
  if (se != null && Math.abs(d) < 1.96 * se) {
    return `<span class="delta ns" title="Difference ${label} is NOT statistically significant at 95% (two-proportion test): n=${fmt.int(run.n_rows)} vs ${fmt.int(bestRun.n_rows)} — CI overlap">≈ ${label}</span>`;
  }
  return `<span class="delta ${d > 0 ? "up" : "down"}" title="Statistically significant vs best on the SAME sample surface (two-proportion z-test, 95%): n=${fmt.int(run.n_rows)} vs ${fmt.int(bestRun?.n_rows ?? "—")}">${label}</span>`;
}

/* ---------- routing ---------- */

async function fetchJson(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${url} -> ${res.status}`);
  return res.json();
}

function parseHash() {
  let m = window.location.hash.match(/^#\/run\/(\d+)\/doc\/(\d+)/);
  if (m) return { view: "doc", id: Number(m[1]), doc: Number(m[2]) };
  m = window.location.hash.match(/^#\/run\/(\d+)/);
  if (m) return { view: "run", id: Number(m[1]) };
  m = window.location.hash.match(/^#\/(task|prompt|model)\/(.+)/);
  if (m) return { view: "group", kind: m[1], key: decodeURIComponent(m[2]) };
  if (window.location.hash.match(/^#\/prompts/)) return { view: "prompts" };
  if (window.location.hash.match(/^#\/benchmarks/)) return { view: "benchmarks" };
  if (window.location.hash.match(/^#\/memos/)) return { view: "memos" };
  return { view: "index" };
}

async function route() {
  const r = parseHash();
  if (r.view === "doc") await renderDoc(r.id, r.doc);
  else if (r.view === "run") await renderRun(r.id);
  else if (r.view === "group") await renderGroup(r.kind, r.key);
  else if (r.view === "prompts") await renderPrompts();
  else if (r.view === "benchmarks") await renderBenchmarks();
  else if (r.view === "memos") await renderMemos();
  else await renderIndex();
}

/* ---------- theme ---------- */

function applyTheme(t) {
  document.documentElement.dataset.theme = t;
  try { localStorage.setItem("theme", t); } catch (e) { /* private mode */ }
  const btn = $("#theme-toggle");
  if (btn) btn.textContent = t === "dark" ? "☀" : "☾";
}

function initTheme() {
  const btn = $("#theme-toggle");
  if (btn) btn.addEventListener("click", () =>
    applyTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark"));
  applyTheme(document.documentElement.dataset.theme || "light");
}

/* ---------- index view ---------- */

function statCards() {
  const m = state.meta;
  const aggs = m.task_aggregates || {};
  const cards = [
    { k: "Runs", v: fmt.int(m.run_count),
      d: Object.entries(m.tasks || {}).map(([t, n]) => `${n} ${t.replace("_", " ")}`).join(" · ") },
    { k: "Documents evaluated", v: fmt.int(m.n_rows),
      d: `${fmt.int(m.n_ok)} ok · ${fmt.int(m.n_error)} errors` },
    { k: "Total tokens", v: fmt.tokens(m.total_tokens) },
    { k: "Models", v: fmt.int(Object.keys(m.models || {}).length),
      d: Object.keys(m.models || {}).join(", ") },
  ];
  const estTotal = state.index.reduce((s, r) => s + (r.cost_estimated_usd || 0), 0);
  if (estTotal > 0) {
    cards.push({
      k: "Total cost (est.)",
      v: `$${estTotal.toFixed(4)}`,
      d: "deterministic token × price across all runs — billed OpenRouter totals shown when the activity CSV is ingested",
    });
  }
  const costs = m.costs;
  if (costs) {
    cards.push({
      k: "Cumulative cost (OpenRouter)",
      v: `$${costs.totals.cost_total_usd.toFixed(4)}`,
      d: `${costs.covered_runs}/${costs.total_runs} runs in export window · ${fmt.int(costs.totals.calls.chat)} chat + ${fmt.int(costs.totals.calls.embeddings)} embedding calls`,
      note: `activity export ${costs.export.start} → ${costs.export.end} UTC (key ${costs.api_key})`,
    });
  }
  for (const task of Object.keys(aggs).sort()) {
    const a = aggs[task];
    cards.push({
      k: `Best · ${task.replace("_", " ")}`,
      v: fmt.pct(a.best.value),
      d: `median ${fmt.pct(a.median)} · worst ${fmt.pct(a.worst.value)} · ${a.runs} runs · ${fmt.int(a.documents ?? 0)} docs`,
      href: `#/run/${a.best.run_id}`,
      best: true,
    });
  }
  return cards
    .map(
      (c) =>
        `<div class="stat ${c.best ? "best" : ""}">
           <div class="k">${esc(c.k)}</div>
           <div class="v">${c.href ? `<a href="${c.href}">${esc(c.v)}</a>` : esc(c.v)}</div>
           ${c.d ? `<div class="d">${esc(c.d)}</div>` : ""}
         </div>`
    )
    .join("");
}

function scoringCard() {
  const g = state.meta.scoring_guide || {};
  const bands = (g.bands || [])
    .map(
      (b) =>
        `<div class="band-legend"><span class="chip ${b.cls}">≥ ${(b.min * 100).toFixed(0)}% · ${esc(b.label)}</span>
         <span class="soft">${esc(b.meaning)}</span></div>`
    )
    .join("");
  const tasks = Object.entries(g.tasks || {})
    .map(([task, t]) => {
      const comps = (t.components || [])
        .map(
          (c) => `<tr><td class="k mono">${esc(c.label)}</td>
                  <td>${esc(c.calculation)}</td>
                  <td>${esc(c.meaning)}</td></tr>`
        )
        .join("");
      return `<div class="sg-task">
        <h3>${taskTag(task)} ${esc(t.headline ? t.headline.label + " (headline)" : "")}</h3>
        <p>${esc(t.summary)}</p>
        <p><strong>Composition — how it's calculated:</strong> ${esc(t.formula)}</p>
        <p><strong>What it conveys:</strong> ${esc(t.conveys)}</p>
        <table class="data sg-table"><thead><tr><th>Metric</th><th>Calculation</th><th>Meaning</th></tr></thead>
        <tbody>${comps}</tbody></table>
      </div>`;
    })
    .join("");
  const refs = g.references || {};
  return `<div class="card sg">
    <details open>
      <summary><h2 style="display:inline">Scoring reference — how to read these numbers</h2></summary>
      <div class="body">
        <p>${esc(g.general || "")}</p>
        <h3>Display bands</h3>
        ${bands}
        <h3>Sample sizes matter</h3>
        <div class="note">
          Every score carries a <strong>Wilson 95% confidence interval</strong> whose width
          shrinks with the sample: n=5 → roughly ±27pp, n=509 → ±2.2pp. The <strong>Δ vs best</strong>
          column is only colored red/green when the difference is <strong>statistically
          significant at 95%</strong> (two-proportion z-test); insignificant deltas are shown
          as “≈” in gray — a 5-document run is never presented as beating or losing to a
          509-document run on bare accuracy. Only same-sample runs (same dataset, seed, and
          size) are directly comparable.
        </div>
        ${tasks}
        <h3>Cost accounting</h3>
        ${costAccountingNote()}
        <p class="soft" style="margin-top:12px">Full formula-level reference:
          <a href="${esc(refs.scoring_md || "")}" target="_blank" rel="noopener">SCORING.md</a> ·
          <a href="${esc(refs.agents_md || "")}" target="_blank" rel="noopener">AGENTS.md scoring model</a></p>
      </div>
    </details>
  </div>`;
}

function costAccountingNote() {
  const c = state.meta.costs;
  if (!c) return `<div class="note">No OpenRouter activity export ingested — rebuild with
    <span class="mono">build_site.py --openrouter-csv &lt;activity.csv&gt;</span> to attach real billed costs.</div>`;
  const perTask = Object.entries(c.per_task)
    .map(([t, v]) => `<span class="mono">${esc(t.replace(/_/g, " "))}</span> $${v.toFixed(4)}`).join(" · ");
  return `<div class="note">
    Costs are the <strong>actual billed totals from the OpenRouter activity log</strong>
    (<span class="mono">${esc(c.source)}</span>, key <span class="mono">${esc(c.api_key)}</span>), not the
    $0.00 usage fields the eval runners recorded (Langfuse/OpenRouter billing isn't captured per-row).
    Every generation under that key for the eval models (qwen/qwen3.7-flash, text-embedding-3-small) is
    attributed to the run whose completion timestamp is the next boundary after the generation time.
    The export covers <strong>${c.export.start} → ${c.export.end} UTC</strong> —
    ${c.covered_runs} of ${c.total_runs} runs; runs outside the window show “—” (export a fresh
    activity CSV and rerun <span class="mono">build_site.py --openrouter-csv</span> to extend coverage).
    Cumulative: <strong>$${c.totals.cost_total_usd.toFixed(4)}</strong> across
    ${fmt.int(c.totals.calls.chat)} chat + ${fmt.int(c.totals.calls.embeddings)} embedding calls
    (${fmt.tokens(c.totals.tokens)} tokens). Per task: ${perTask}.
  </div>`;
}

function options(rows, get, placeholder) {
  const values = [...new Set(rows.map(get))].filter(Boolean).sort();
  return (
    `<option value="">${placeholder}</option>` +
    values.map((v) => `<option>${esc(v)}</option>`).join("")
  );
}

function bestRunFor(task) {
  const b = (state.meta.task_aggregates || {})[task]?.best;
  if (!b) return null;
  return state.index.find((r) => r.id === b.run_id) || null;
}

/* Cost cell: the OpenRouter-CSV BILLED total when covered (ground truth),
 * else the deterministic token x price ESTIMATE (every run is scored). */
function costCell(run) {
  const c = run.cost;
  if (c && c.covered) {
    const tip = `${fmt.int(c.calls.total)} calls in the OpenRouter activity log (${fmt.int(c.calls.chat)} chat + ${fmt.int(c.calls.embeddings)} embeddings)`;
    return `<span class="mono" title="${esc(tip)}">
      $${c.cost_total_usd.toFixed(4)}
      <div class="faint" style="font-size:11px">$${c.cost_avg_per_doc_usd.toFixed(4)}/doc · billed</div>
    </span>`;
  }
  if (run.cost_estimated_usd != null) {
    const src = run.cost_price_source;
    const tip = src
      ? `Deterministic estimate: ${fmt.tokens(run.total_tokens)} tokens x ${esc(src.model)} ($${src.in_per_1m}/1M in · $${src.out_per_1m}/1M out)`
      : "Deterministic estimate from recorded tokens";
    return `<span class="mono faint" title="${esc(tip)}">
      $${run.cost_estimated_usd.toFixed(4)}
      <div class="faint" style="font-size:11px">$${(run.cost_estimated_per_doc_usd ?? 0).toFixed(4)}/doc · est.</div>
    </span>`;
  }
  return `<span class="faint" title="No token data / unknown model price">—</span>`;
}

function indexTable(rows) {
  if (!rows.length) return '<div class="empty">No runs match the current filters.</div>';
  const key = state.sortKey;
  const dir = state.sortDir === "desc" ? -1 : 1;
  const sorted = [...rows].sort((a, b) => {
    const va = a[key], vb = b[key];
    if (key === "headline") return ((va?.value ?? -1) - (vb?.value ?? -1)) * dir;
    if (key === "cost") return ((a.cost?.cost_total_usd ?? -1) - (b.cost?.cost_total_usd ?? -1)) * dir;
    // Numeric columns sort NUMERICALLY — id is the chronological run number,
    // so it must never fall through to the lexicographic string compare
    // (which put "9" before "43" and buried the newest runs mid-table).
    if (key === "id" || key === "total_tokens" || key === "n_rows" || key === "n_error" || key === "delta_best_pp")
      return ((Number(va) ?? -1) - (Number(vb) ?? -1)) * dir;
    return String(va ?? "").localeCompare(String(vb ?? "")) * dir;
  });
  const cols = [
    ["#", "id", true], ["Experiment", "experiment_name"], ["Task", "task"],
    ["Model", "model"], ["Prompt(s)", "prompts"], ["Score", "headline"],
    ["Δ vs best", "delta_best_pp", true], ["Rows", "n_rows", true],
    ["Errors", "n_error", true], ["Tokens", "total_tokens", true],
    ["Cost", "cost", true], ["Run at", "timestamp"],
  ];
  const arrow = (k) => (key === k ? `<span class="arrow">${state.sortDir === "asc" ? "▲" : "▼"}</span>` : "");
  const head = cols
    .map(([label, k, num]) => `<th class="${num ? "num" : ""}" data-key="${k}" title="${k === "delta_best_pp" ? "colored only when statistically significant (95%, two-proportion test)" : ""}">${label}${arrow(k)}</th>`)
    .join("");
  const body = sorted
    .map((r) => {
      const err = r.n_error || 0;
      return `<tr data-id="${r.id}">
        <td class="num faint">${r.id}</td>
        <td><span class="mono">${esc(r.experiment_name)}</span>
            ${r.git ? `<div class="faint" style="font-size:11px">@${esc(r.git.commit)}</div>` : ""}</td>
        <td>${taskTag(r.task, true)}</td>
        <td class="mono">${r.model ? `<a href="#/model/${encodeURIComponent(r.model)}" data-nav-stop>${esc(r.model)}</a>` : "—"}</td>
        <td class="mono">${r.prompts && r.prompts !== "—" ? `<a href="#/prompt/${encodeURIComponent(r.prompts)}" data-nav-stop>${esc(r.prompts)}</a>` : esc(r.prompts)}</td>
        <td>${headlineCell(r.headline, r)}</td>
        <td class="num" style="white-space:nowrap">${deltaCell(r, bestRunFor(r.task))}</td>
        <td class="num">${fmt.int(r.n_rows)}</td>
        <td class="num">${err > 0 ? `<span class="delta down">${err}</span>` : `<span class="faint">0</span>`}</td>
        <td class="num">${fmt.tokens(r.total_tokens)}</td>
        <td class="num" style="white-space:nowrap">${costCell(r)}</td>
        <td class="num faint" style="white-space:nowrap">${fmt.date(r.timestamp)}</td>
      </tr>`;
    })
    .join("");
  return `<div class="table-wrap"><table class="data"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`;
}

function applyFilters() {
  const q = ($("#q").value || "").toLowerCase();
  const task = $("#f-task").value;
  const model = $("#f-model").value;
  const prompt = $("#f-prompt").value;
  const minN = Number($("#f-minn").value || 0);
  const rows = state.index.filter(
    (r) =>
      (!q ||
        [r.experiment_name, r.model, r.prompts, r.task, r.git?.commit]
          .join(" ")
          .toLowerCase()
          .includes(q)) &&
      (!task || r.task === task) &&
      (!model || r.model === model) &&
      (!prompt || r.prompts === prompt) &&
      (r.n_rows || 0) >= minN
  );
  $("#run-count").textContent = `${rows.length} of ${state.index.length} runs`;
  $("#index-table").innerHTML = indexTable(rows);
}

function bindFilters() {
  for (const id of ["q", "f-task", "f-model", "f-prompt", "f-minn"]) {
    $("#" + id).addEventListener("input", applyFilters);
  }
  $("#index-table").addEventListener("click", (e) => {
    const stop = e.target.closest("[data-nav-stop]");
    if (stop) { e.stopPropagation(); return; }
    const tr = e.target.closest("tr[data-id]");
    if (tr) window.location.hash = `#/run/${tr.dataset.id}`;
  });
  $("#index-table").addEventListener("click", (e) => {
    const th = e.target.closest("th[data-key]");
    if (!th) return;
    const k = th.dataset.key;
    if (state.sortKey === k) {
      state.sortDir = state.sortDir === "asc" ? "desc" : "asc";
    } else {
      state.sortKey = k;
      state.sortDir = ["id", "headline", "delta_best_pp", "n_rows", "n_error", "total_tokens", "cost"].includes(k)
        ? "desc" : "asc";
    }
    applyFilters();
  });
}

async function renderIndex() {
  if (!state.meta) {
    const [meta, index] = await Promise.all([
      fetchJson("data/meta.json"),
      fetchJson("data/index.json"),
    ]);
    state.meta = meta;
    state.index = index;
  }
  $("#view").innerHTML = `
    <div class="stats">${statCards()}</div>
    ${scoringCard()}
    <div class="card">
      <h2>Runs</h2>
      <div class="filters">
        <input type="search" id="q" placeholder="Search experiment, prompt, model, commit…" />
        <select id="f-task"></select>
        <select id="f-model"></select>
        <select id="f-prompt"></select>
        <select id="f-minn" title="Only show runs with at least this many documents — small samples have wide confidence intervals">
          <option value="0">any sample size</option>
          <option value="10">n ≥ 10</option>
          <option value="50">n ≥ 50</option>
          <option value="100">n ≥ 100</option>
          <option value="200">n ≥ 200</option>
          <option value="500">n ≥ 500</option>
        </select>
        <span class="count" id="run-count"></span>
      </div>
      <div id="index-table"></div>
    </div>`;
  $("#f-task").innerHTML = options(state.index, (r) => r.task, "All tasks");
  $("#f-model").innerHTML = options(state.index, (r) => r.model, "All models");
  $("#f-prompt").innerHTML = options(state.index, (r) => r.prompts, "All prompts");
  bindFilters();
  applyFilters();
}

/* ---------- group views (task / prompt / model) ---------- */

function groupHeader(kind, key) {
  const label = kind === "task" ? "Task" : kind === "prompt" ? "Prompt version" : "Model";
  return `<a class="back" href="#/">← All runs</a>
    <div class="detail-head">
      <h2><span class="mono">${esc(key)}</span></h2>
      <div class="meta-line">${esc(label)} · ${kind === "task" ? taskTag(key) : ""}</div>
    </div>`;
}

function groupStats(kind, key, runs) {
  const values = runs.map((r) => r.headline?.value).filter((v) => v != null);
  const docs = runs.reduce((s, r) => s + (r.n_rows || 0), 0);
  const toks = runs.reduce((s, r) => s + (r.total_tokens || 0), 0);
  const sorted = [...values].sort((a, b) => a - b);
  const median = sorted.length
    ? sorted.length % 2
      ? sorted[(sorted.length - 1) / 2]
      : (sorted[sorted.length / 2 - 1] + sorted[sorted.length / 2]) / 2
    : null;
  const best = values.length ? Math.max(...values) : null;
  const worst = values.length ? Math.min(...values) : null;
  const bestRun = runs.find((r) => r.headline?.value === best);
  const covered = runs.filter((r) => r.cost?.covered);
  const costTotal = covered.reduce((s, r) => s + (r.cost.cost_total_usd || 0), 0);
  const cards = [
    { k: "Runs", v: fmt.int(runs.length) },
    { k: "Documents", v: fmt.int(docs) },
    { k: "Tokens", v: fmt.tokens(toks) },
    { k: "Best", v: fmt.pct(best), href: bestRun ? `#/run/${bestRun.id}` : null },
    { k: "Median", v: fmt.pct(median) },
    { k: "Worst", v: fmt.pct(worst) },
  ];
  if (state.meta.costs) {
    cards.push({
      k: "Cost (covered)",
      v: costTotal > 0 ? `$${costTotal.toFixed(4)}` : "—",
      d: `${covered.length}/${runs.length} runs in export window`,
    });
  }
  return `<div class="stats">${cards.map((c) =>
    `<div class="stat"><div class="k">${esc(c.k)}</div><div class="v">${c.href ? `<a href="${c.href}">${esc(c.v)}</a>` : esc(c.v)}</div></div>`).join("")}</div>`;
}

function groupByTable(kind, runs) {
  /* task -> group by prompt; prompt/model -> group by task. */
  const groupKey = kind === "task" ? "prompts" : "task";
  const groups = new Map();
  for (const r of runs) {
    const k = r[groupKey] || "—";
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(r);
  }
  const rows = [...groups.entries()]
    .map(([key, rs]) => {
      const values = rs.map((r) => r.headline?.value).filter((v) => v != null);
      const best = values.length ? Math.max(...values) : null;
      const sorted = [...values].sort((a, b) => a - b);
      const median = sorted.length
        ? sorted.length % 2
          ? sorted[(sorted.length - 1) / 2]
          : (sorted[sorted.length / 2 - 1] + sorted[sorted.length / 2]) / 2
        : null;
      const docs = rs.reduce((s, r) => s + (r.n_rows || 0), 0);
      const bestRun = rs.find((r) => r.headline?.value === best);
      const target = groupKey === "prompts" ? `#/prompt/${encodeURIComponent(key)}` : `#/task/${encodeURIComponent(key)}`;
      return `<a class="group-row" href="${target}" data-nav-stop style="display:grid">
        <span class="gname mono">${esc(key)}</span>
        <span class="gval">${fmt.int(rs.length)} runs</span>
        <span class="gval">${fmt.int(docs)} docs</span>
        <span class="gval">${fmt.pct(best)}${bestRun ? ` <span class="faint">run ${bestRun.id}</span>` : ""}</span>
        <span class="gval faint">median ${fmt.pct(median)}</span>
      </a>`;
    })
    .join("");
  return `<div class="card"><h2>Grouped by ${groupKey === "prompts" ? "prompt version" : groupKey}</h2>
    <div class="group-grid">
      <div class="group-row" style="font-weight:650;color:var(--text-faint);font-size:11px;text-transform:uppercase;letter-spacing:.05em">
        <span>${groupKey === "prompts" ? "Prompt" : "Task"}</span><span class="gval">Runs</span><span class="gval">Docs</span><span class="gval">Best</span><span class="gval">Median</span>
      </div>
      ${rows}
    </div></div>`;
}

async function issue1Charts(kind, key) {
  /* Issue #1 display: trend line, cost-vs-quality scatter, failure-mode
   * stacked bars — only on the per-task view. */
  if (kind !== "task") return "";
  if (!state.trends) {
    try { state.trends = await fetchJson("data/trends.json"); }
    catch (e) { state.trends = { tasks: {} }; }
  }
  const series = (state.trends.tasks || {})[key] || [];
  if (!series.length) return "";
  const parts = [trendChartHtml(series, key), scatterChartHtml(series)];
  if (key === "subtype_classification") parts.push(failureModeBarsHtml(series));
  return parts.join("");
}

async function renderGroup(kind, key) {
  if (!state.meta) {
    const [meta, index] = await Promise.all([
      fetchJson("data/meta.json"),
      fetchJson("data/index.json"),
    ]);
    state.meta = meta;
    state.index = index;
  }
  const runs = state.index.filter((r) =>
    kind === "task" ? r.task === key : kind === "prompt" ? r.prompts === key : r.model === key);
  if (!runs.length) {
    $("#view").innerHTML = `<div class="empty">No runs for ${esc(kind)} ${esc(key)}.</div>`;
    return;
  }
  $("#view").innerHTML = `
    ${groupHeader(kind, key)}
    ${groupStats(kind, key, runs)}
    ${groupByTable(kind, runs)}
    ${await issue1Charts(kind, key)}
    <div class="card"><h2>Runs</h2>
      <div class="filters">
        <input type="search" id="q" placeholder="Filter these runs…" />
        <span class="count" id="run-count"></span>
      </div>
      <div id="index-table"></div>
    </div>`;
  const localFilter = () => {
    const q = ($("#q").value || "").toLowerCase();
    const rows = runs.filter((r) => !q ||
      [r.experiment_name, r.model, r.prompts, r.task, r.git?.commit].join(" ").toLowerCase().includes(q));
    $("#run-count").textContent = `${rows.length} of ${runs.length} runs`;
    $("#index-table").innerHTML = indexTable(rows);
  };
  $("#q").addEventListener("input", localFilter);
  $("#index-table").addEventListener("click", (e) => {
    const stop = e.target.closest("[data-nav-stop]");
    if (stop) { e.stopPropagation(); return; }
    const tr = e.target.closest("tr[data-id]");
    if (tr) window.location.hash = `#/run/${tr.dataset.id}`;
  });
  wireChartInteractions($("#view"));
  localFilter();
  window.scrollTo(0, 0);
}

/* ---------- run detail view ---------- */

function kvRowsTyped(obj) {
  return Object.entries(obj || {})
    .map(([k, v]) => {
      let html;
      if (typeof v === "boolean") html = v ? "yes" : "no";
      else if (typeof v === "number") html = v.toFixed(4).replace(/0+$/, "").replace(/\.$/, "");
      else if (v === null || v === undefined || v === "") html = "—";
      else html = esc(v);
      return `<tr><td class="k">${esc(k)}</td><td class="v">${html}</td></tr>`;
    })
    .join("");
}

function scoreRows(obj) {
  return Object.entries(obj || {})
    .map(
      ([name, v]) =>
        `<div class="score-row"><div class="name">${esc(name)}</div>
         <div class="track"><i class="${band(v)?.cls ?? ""}" style="width:${v == null ? 0 : (Math.max(0, Math.min(1, v)) * 100).toFixed(1)}%"></i></div>
         <div class="value">${v == null ? "—" : fmt.pct(v)}</div></div>`
    )
    .join("");
}

function kvCard(title, body, flush = false) {
  return `<div class="card"><h2>${esc(title)}</h2><div class="body${flush ? " flush" : ""}">${body}</div></div>`;
}

function metricCard(k, v, opts = {}) {
  const isRatio = opts.kind !== "count";
  const b = isRatio ? band(v) : null;
  const val = v == null
    ? "—"
    : isRatio
      ? `${fmt.pct(v)} <span class="faint mono" style="font-size:12px">${fmt.score(v)}</span>`
      : fmt.int(v);
  const chip = b ? ` <span class="chip ${b.cls}">${b.label}</span>` : "";
  const nBadge = opts.n ? ` <span class="badge" title="sample size — CI width shrinks with n">n=${fmt.int(opts.n)}</span>` : "";
  return `<div class="stat ${opts.best ? "best" : ""}">
    <div class="k">${esc(k)}</div>
    <div class="v">${val}${chip}${nBadge}</div>
    ${opts.d ? `<div class="d">${esc(opts.d)}</div>` : ""}
    ${opts.note ? `<div class="d faint">${esc(opts.note)}</div>` : ""}
  </div>`;
}

function compositionCard(run) {
  const task = run.task;
  const scores = run.scores || {};
  let rows = "";
  if (task === "contract_entity_extraction") {
    rows = scoreRows({
      "overall extraction": scores.overall_extraction_score,
      "field presence": scores.field_presence,
      "schema valid": scores.schema_valid,
    }) + (scores.per_field ? scoreRows(scores.per_field) : "");
  } else if (task === "chained_sorter_extractor") {
    rows = scoreRows({
      "sorter doc-type match": scores.sorter?.exact_match,
      "sorter subtype accuracy": scores.sorter?.subtype_accuracy,
      "extractor overall": scores.extractor?.overall_extraction_score,
      "extractor field presence": scores.extractor?.field_presence,
      "extractor verified precision": scores.extractor?.overall_verified_precision,
      "extractor category presence": scores.extractor?.category_presence,
    });
  } else if (task === "subtype_classification") {
    rows = scoreRows({
      "doc-type accuracy": scores.sorter?.exact_match,
      "subtype strict": scores.sorter?.subtype_accuracy,
      "subtype equiv": scores.sorter?.subtype_accuracy_equiv,
      confidence: scores.sorter?.confidence,
    });
  }
  return kvCard("Score composition", `<div style="max-width:640px">${rows}</div>`);
}

function resultsTable(run, runId) {
  const task = run.task;
  const rows = (run.results || [])
    .map((res, i) => {
      const sorter = res.sorter || {};
      const expandId = `r${runId}-d${i}`;
      const detail =
        task === "subtype_classification"
          ? `<tr class="insight-row" data-expand="${expandId}" hidden>
               <td colspan="6">
                 <div class="kv" style="max-width:760px">${kvRowsTyped({
                   "doc type": sorter.doc_type,
                   "expected subtype": sorter.expected_subtype,
                   "predicted subtype": sorter.contract_subtype,
                   "doc type ok": sorter.doc_type_ok,
                   "subtype ok": sorter.subtype_ok,
                   "subtype ok (equiv)": sorter.subtype_ok_equiv,
                   truncated: sorter.truncated,
                 })}</div>
                 ${sorter.reasoning ? `<div class="reasoning">${esc(sorter.reasoning)}</div>` : ""}
               </td></tr>`
          : task === "chained_sorter_extractor"
            ? `<tr class="insight-row" data-expand="${expandId}" hidden>
                 <td colspan="6">
                   <div class="kv" style="max-width:760px">${kvRowsTyped({
                     "sorter subtype": sorter.contract_subtype,
                     "expected subtype": sorter.expected_subtype,
                     "sorter doc type ok": sorter.doc_type_ok,
                     "sorter subtype ok": sorter.subtype_ok,
                     confidence: sorter.confidence,
                   })}</div>
                   ${sorter.reasoning ? `<div class="reasoning" style="margin-top:6px">${esc(sorter.reasoning)}</div>` : ""}
                 </td></tr>`
            : `<tr class="insight-row" data-expand="${expandId}" hidden>
                 <td colspan="6">
                   <div class="score-rows" style="max-width:560px">${scoreRows(res.field_scores)}</div>
                   ${res.ambiguous_fields?.length ? `<div class="soft" style="margin-top:6px">ambiguous fields: <span class="mono">${esc(res.ambiguous_fields.join(", "))}</span></div>` : ""}
                   ${res.error ? `<div class="reasoning" style="margin-top:6px">${esc(res.error)}</div>` : ""}
                 </td></tr>`;
      const status = res.status === "completed"
        ? '<span class="badge" style="color:var(--good);border-color:#b7e0c5;background:#eef8f1">ok</span>'
        : `<span class="badge" style="color:var(--bad);border-color:#f2c8c8;background:#fdf0f0">${esc(res.status)}</span>`;
      const score = task === "contract_entity_extraction"
        ? res.overall_score
        : task === "chained_sorter_extractor"
          ? res.extractor_scores?.overall_score ?? res.overall_score
          : res.sorter?.subtype_ok === true ? 1 : res.sorter?.subtype_ok === false ? 0 : null;
      const scoreCell = score == null ? '<span class="faint">—</span>'
        : `<strong>${fmt.pct(score)}</strong>${barHtml(score)}`;
      const toks = task === "subtype_classification"
        ? res.sorter_tokens?.total_tokens
        : task === "chained_sorter_extractor"
          ? (res.sorter_tokens?.total_tokens ?? 0) + (res.extractor_tokens?.total_tokens ?? 0)
          : res.tokens?.total_tokens;
      const name = task === "contract_entity_extraction"
        ? res.filename
        : (res.filename || "").split("_").slice(-2).join(" ");
      return `<tr data-expand-row="${expandId}">
        <td class="mono" style="max-width:340px;overflow-wrap:anywhere" title="${esc(res.filename || "")}">${esc(name)}</td>
        <td>${status}</td>
        <td>${scoreCell}</td>
        <td class="num">${fmt.tokens(toks)}</td>
        <td class="num">${fmt.int(res.tokens?.prompt_tokens ?? res.sorter_tokens?.prompt_tokens ?? null)}</td>
        <td><a class="trace-link" href="#/run/${runId}/doc/${i}">view trace →</a></td>
      </tr>${detail}`;
    })
    .join("");
  return `<div class="table-wrap"><table class="data">
    <thead><tr>
      <th>Document</th><th>Status</th><th>Score</th><th class="num">Tokens</th>
      <th class="num">Prompt tokens</th><th>Trace</th>
    </tr></thead><tbody>${rows}</tbody></table></div>`;
}

function confusionMatrix(cm) {
  /* Expected x predicted counts, rows sorted by expected frequency (desc) so
   * the classes that matter most lead the matrix; every row carries its
   * total + per-class accuracy (diagonal / total). */
  const subtypes = Object.keys(cm || {}).sort();
  if (!subtypes.length) return "";
  const rows = subtypes.map((expected) => {
    const row = subtypes.map((predicted) => cm[expected][predicted] || 0);
    const total = row.reduce((a, b) => a + b, 0);
    return { expected, row, total };
  }).sort((a, b) => b.total - a.total || a.expected.localeCompare(b.expected));
  const ordered = rows.map((r) => r.expected);
  const cells = rows
    .map(({ expected, row, total }) => {
      const diag = row[ordered.indexOf(expected)] || 0;
      const acc = total ? (diag / total) : null;
      return `<tr>
        <td class="mono" title="${esc(expected)}">${esc(expected)}${acc != null ? ` <span class="faint" style="font-size:10px">(${fmt.pct(acc)})</span>` : ""}</td>` +
        row.map((count, j) => {
          const isDiag = ordered[j] === expected;
          const cls = isDiag
            ? count > 0 ? 'style="background:#eef8f1;color:var(--good)"' : ""
            : count > 0 ? 'style="background:#fdf0f0;color:var(--bad)"' : "";
          const tip = isDiag ? `${esc(expected)} correctly classified` : `expected ${esc(expected)} → predicted ${esc(ordered[j])}`;
          return `<td class="num" ${cls} title="${tip}">${count || "·"}</td>`;
        }).join("") +
        `<td class="num faint" title="total expected rows">${total}</td></tr>`;
    })
    .join("");
  const head = ordered.map((s) => `<th class="mono" title="predicted ${esc(s)}">${esc(s)}</th>`).join("");
  return `<div class="table-wrap" style="max-height:420px;overflow:auto"><table class="data">
    <thead><tr><th class="mono">expected \\ predicted</th>${head}<th class="num mono" title="rows expected">Σ</th></tr></thead>
    <tbody>${cells}</tbody></table>
    <div class="faint" style="font-size:11px;margin-top:4px">Rows sorted by expected frequency; accuracy = diagonal / row total.</div>`;
}

async function renderRun(id) {
  const run = await fetchJson(`data/runs/${String(id).padStart(3, "0")}.json`);
  const summary = state.index.find((r) => r.id === id) || null;
  const task = run.task;
  const tokens = run.tokens || {};
  const total = tokens.total || tokens;
  const scores = run.scores || {};
  const sorter = scores.sorter || {};
  const extractor = task === "contract_entity_extraction" ? scores : scores.extractor || {};
  const dataSource = run.data_source || {};
  const git = run.git || {};
  const n = run.n_rows;

  const cards = [];
  if (task === "subtype_classification") {
    cards.push(metricCard("Doc-type accuracy", sorter.exact_match, { d: "primary class == contract", note: "exact_match", n }));
    cards.push(metricCard("Subtype strict", sorter.subtype_accuracy, { d: "exact CUAD folder", best: true, n }));
    cards.push(metricCard("Subtype equiv", sorter.subtype_accuracy_equiv, { d: "strict or defensible family", n }));
    cards.push(metricCard("Confidence", sorter.confidence, { d: "mean model-reported confidence" }));
    cards.push(metricCard("Failed rows", sorter.failure_insights?.n_failed, { kind: "count", d: Object.entries(sorter.failure_insights?.mode_counts || {}).map(([m, x]) => `${m} ×${x}`).join(" · ") }));
  } else if (task === "chained_sorter_extractor") {
    cards.push(metricCard("Extractor score", scores.extractor?.overall_extraction_score, { d: "end-to-end extraction quality", best: true, n }));
    cards.push(metricCard("Sorter doc-type", scores.sorter?.exact_match, { d: "routing to contract path", n }));
    cards.push(metricCard("Verified precision", extractor.overall_verified_precision, { d: "factuality guard — grounded items", n }));
    cards.push(metricCard("Field presence", extractor.field_presence, { d: "share of expected fields populated", n }));
    cards.push(metricCard("Category presence", extractor.category_presence, { d: "CUAD clause coverage", n }));
  } else {
    cards.push(metricCard("Overall extraction", scores.overall_extraction_score, { d: "composite of per-field content scores", best: true, n }));
    cards.push(metricCard("Field presence", scores.field_presence, { d: "share of expected fields populated", n }));
    cards.push(metricCard("Schema valid", scores.schema_valid, { d: "parseable, conformant JSON output", n }));
    cards.push(metricCard("Errors", run.n_error ?? 0, { kind: "count", d: `of ${fmt.int(run.n_rows)} rows` }));
  }

  const sections = [];
  sections.push(`<div class="score-grid">${cards.join("")}</div>`);
  sections.push(compositionCard(run));

  /* Issue #1: judge-calibration tracker (extraction --judge runs) and the
   * chained error-propagation ablation (--handoff-scope ground_truth). */
  if (scores.judge_calibration) {
    const jc = scores.judge_calibration;
    const agree = jc.agree_rate == null ? "—" : fmt.pct(jc.agree_rate);
    const lean = jc.judge_lenient > jc.judge_strict ? "judge leans LENIENT"
      : jc.judge_strict > jc.judge_lenient ? "judge leans STRICT" : "no lean";
    sections.push(kvCard("Judge calibration (issue #1)", `
      <table class="kv">${kvRowsTyped({
        "rows judged": jc.n_judged,
        "rows scored": jc.n_scored,
        "agree rate (judge vs deterministic)": agree,
        "judge strict (det strong, judge inaccurate)": jc.judge_strict,
        "judge lenient (det weak, judge accurate)": jc.judge_lenient,
        lean,
        "bands": `strong ≥ ${jc.bands?.strong_ge} · weak ≤ ${jc.bands?.weak_le}`,
        "judgments file": jc.judgments_file,
      })}</table>
      <div class="note">Deterministic-vs-LLM-judge agreement over the rows the judge actually reviewed (the ambiguous band). A systematic lean means trusting the judge more broadly needs calibration, not confidence.</div>`));
  }
  if (scores.ablation) {
    const ab = scores.ablation;
    sections.push(kvCard("Error-propagation ablation (issue #1)", `
      <table class="kv">${kvRowsTyped({
        "extractor score — predicted-subtype handoff": ab.predicted_handoff_overall,
        "extractor score — ground-truth-subtype handoff": ab.ground_truth_handoff_overall,
        "sorter routing loss (pp)": ab.sorter_loss_pp,
        "docs compared": ab.n_docs,
      })}</table>
      <div class="note">Same documents, same model/prompt — only the subtype handoff differs. The gap is the sorter's routing error; the rest of the chained loss is the specialist's.</div>`));
  }

  sections.push(kvCard("Run metadata", `
    <table class="kv">${kvRowsTyped({
      timestamp: run.timestamp,
      experiment: run.experiment_name,
      task,
      model: run.model,
      prompts: run.prompt_versions ? Object.values(run.prompt_versions).join(" + ") : run.prompt_version,
      "git commit": git.commit ? `${git.commit}${git.dirty ? " (dirty)" : ""}` : null,
      "data source": dataSource.project,
      "rows / ok / errors": `${run.n_rows} / ${run.n_ok ?? "—"} / ${run.n_error ?? 0}`,
      seed: dataSource.seed,
      "n samples": dataSource.n_samples,
      fingerprint: dataSource.dataset_fingerprint,
    })}</table>`));

  sections.push(kvCard("Parameters", `<table class="kv">${kvRowsTyped(run.parameters)}</table>`));

  const costZero = (total.cost_total_usd || 0) === 0;
  const runCost = summary?.cost;
  const costBlock = runCost?.covered
    ? `<div class="note"><strong>OpenRouter billing (from activity log ${esc(state.meta.costs?.source || "")}):</strong>
        total <strong>$${runCost.cost_total_usd.toFixed(4)}</strong> · avg <strong>$${runCost.cost_avg_per_doc_usd.toFixed(4)}/document</strong>
        · avg ${fmt.int(runCost.tokens_avg_per_doc)} tokens/document · ${fmt.int(runCost.calls.total)} calls
        (${fmt.int(runCost.calls.chat)} chat + ${fmt.int(runCost.calls.embeddings)} embeddings;
        ${fmt.int(runCost.tokens.prompt)} prompt + ${fmt.int(runCost.tokens.completion)} completion tokens).</div>`
    : state.meta.costs
      ? `<div class="note faint">No generations for this run in the exported OpenRouter activity window
         (${esc(state.meta.costs.export.start)} → ${esc(state.meta.costs.export.end)} UTC) — export a fresh activity CSV
         and rerun <span class="mono">build_site.py --openrouter-csv</span> to bill this run.</div>`
      : "";
  const est = summary?.cost_estimated_usd;
  const estBlock = est != null
    ? `<div class="note"><strong>Deterministic cost estimate:</strong> <strong>$${est.toFixed(4)}</strong>
        total · <strong>$${(summary.cost_estimated_per_doc_usd ?? 0).toFixed(4)}/document</strong>
        (${fmt.tokens(total.total_tokens)} tokens × ${summary?.cost_price_source?.model
          ? `<span class="mono">${esc(summary.cost_price_source.model)}</span> $${summary.cost_price_source.in_per_1m}/1M in · $${summary.cost_price_source.out_per_1m}/1M out`
          : "recorded prices"}) — OpenRouter usage payloads carry no cost, so every run is scored
        from its token counts (see src/cost_models.py).</div>`
    : `<div class="note faint">No cost estimate — no recorded tokens or unknown model price.</div>`;
  sections.push(kvCard("Tokens & cost", `
    <table class="kv">${kvRowsTyped({
      "prompt tokens": total.prompt_tokens,
      "completion tokens": total.completion_tokens,
      "total tokens": total.total_tokens,
      "mean cost (usd, from usage)": total.cost_usd,
      "total cost (usd, from usage)": total.cost_total_usd,
      "cost estimate (usd, tokens x price)": est,
      "rows with usage": total.rows_with_usage,
    })}</table>
    ${estBlock}
    ${costZero && !runCost?.covered ? `<div class="note">The usage-recorded cost is $0.00 (OpenRouter usage payloads carry no cost) — the estimate above scores this run; real billed totals come from the OpenRouter activity log CSV (rebuild with <span class="mono">--openrouter-csv</span>).</div>` : ""}
    ${costBlock}`));

  if (task === "contract_entity_extraction") {
    sections.push(kvCard("Per-field content scores", `
      <div style="max-width:640px">${scoreRows({
        "overall extraction": scores.overall_extraction_score,
        "field presence": scores.field_presence,
        "schema valid": scores.schema_valid,
      })}${scores.per_field ? scoreRows(scores.per_field) : ""}</div>
      <div class="note">Entity-list fields (parties, key_obligations, termination_clauses) report ground-truth coverage — extra correct extractions don't cut the score. See the scoring reference for per-field-type scoring.</div>`));
  } else if (task === "chained_sorter_extractor") {
    sections.push(kvCard("Sorter stage scores", `<div style="max-width:640px">${scoreRows(scores.sorter)}</div>`));
    sections.push(kvCard("Extractor stage scores", `<div style="max-width:640px">${scoreRows(extractor)}</div>`));
  } else {
    const perSubtype = sorter.per_subtype || {};
    const keys = Object.keys(perSubtype).sort();
    sections.push(kvCard("Per-subtype accuracy", `
      <div class="table-wrap"><table class="data">
        <thead><tr><th>Subtype</th><th class="num">Strict</th><th class="num">Equiv</th><th class="num">Correct</th><th class="num">Total</th><th style="width:30%"></th></tr></thead>
        <tbody>${keys.map((k) => `<tr><td class="mono">${esc(k)}</td>
          <td class="num">${fmt.pct(perSubtype[k].accuracy)}</td>
          <td class="num">${fmt.pct(perSubtype[k].accuracy_equiv)}</td>
          <td class="num">${fmt.int(perSubtype[k].correct)}</td>
          <td class="num">${fmt.int(perSubtype[k].total)}</td>
          <td>${barHtml(perSubtype[k].accuracy)}</td></tr>`).join("")}</tbody>
      </table></div>`));
    if (sorter.confusion_matrix) {
      sections.push(kvCard("Confusion matrix", confusionMatrix(sorter.confusion_matrix)));
    }
    const fi = sorter.failure_insights || {};
    const failures = (fi.failures || [])
      .map(
        (f) => `<tr class="insight-row">
          <td class="mono" style="max-width:340px;overflow-wrap:anywhere">${esc(f.filename)}</td>
          <td class="mono">${esc(f.expected)}</td>
          <td class="mono">${esc(f.predicted)}</td>
          <td><span class="mode-chip">${esc(f.mode)}</span></td>
          <td>${f.equiv_recovered ? '<span class="badge" style="color:var(--good)">recovered</span>' : ""}</td>
        </tr>
        <tr class="insight-row"><td></td><td colspan="4"><div class="reasoning">${esc(f.reasoning)}</div></td></tr>`
      )
      .join("");
    if (failures) {
      sections.push(kvCard(`Failed classification insights (${fmt.int(fi.n_failed)})`, `
        <div class="table-wrap"><table class="data">
          <thead><tr><th>Document</th><th>Expected</th><th>Predicted</th><th>Mode</th><th></th></tr></thead>
          <tbody>${failures}</tbody></table></div>`));
    }
  }

  sections.push(kvCard(`Per-document results (${fmt.int(run.n_rows)})`, resultsTable(run, id)));

  const headline = headlineCell(summary?.headline, summary);
  $("#view").innerHTML = `
    <a class="back" href="#/">← All runs</a>
    <div class="detail-head">
      <h2><span class="mono">${esc(run.experiment_name)}</span></h2>
      <div class="meta-line">${taskTag(task, true)} · ${esc(run.model)} · run #${id} · ${fmt.date(run.timestamp)} · ${headline}</div>
    </div>
    ${sections.join("")}`;

  $("#view").addEventListener("click", (e) => {
    const tr = e.target.closest("tr[data-expand-row]");
    if (!tr) return;
    const detailRow = document.querySelector(`tr[data-expand="${tr.dataset.expandRow}"]`);
    if (detailRow) detailRow.hidden = !detailRow.hidden;
  });
  window.scrollTo(0, 0);
}

/* ---------- single-document trace view ---------- */

const EXTRACTION_INTERPRETATION =
  "Field scores are type-aware (SCORING.md §3): dates/money/IDs are exact-after-normalize; " +
  "names use normalized fuzzy matching (Jaro-Winkler + token-set ratio); free-text uses SQuAD " +
  "token F1; entity lists use optimal bipartite matching (threshold 0.6) reported as " +
  "ground-truth coverage for partial-GT fields (parties, key_obligations, termination_clauses); " +
  "containment fields (governing_law, term_length, renewal_terms) are scored by expected-token coverage.";

/* Factuality audit table — the "why" behind verified_precision. */
function entityAuditTable(audit) {
  if (!audit || !Object.keys(audit).length) return "";
  const rows = Object.entries(audit)
    .map(([field, a]) => {
      const bad = (a.hallucinated || 0) > 0;
      return `<tr>
        <td class="mono">${esc(field)}</td>
        <td class="num">${fmt.int(a.n_predicted)}</td>
        <td class="num">${fmt.int(a.matched_gt)}</td>
        <td class="num">${fmt.int(a.verified_in_doc)}</td>
        <td class="num">${fmt.int(a.true_items)}</td>
        <td class="num">${bad ? `<span class="delta down">${fmt.int(a.hallucinated)}</span>` : `<span class="faint">0</span>`}</td>
        <td class="num">${a.verified_precision == null ? "—" : fmt.pct(a.verified_precision)}</td>
        <td class="num">${a.hallucination_rate == null ? "—" : fmt.pct(a.hallucination_rate)}</td>
      </tr>`;
    })
    .join("");
  return kvCard("Entity-list factuality audit", `
    <div class="table-wrap"><table class="data">
      <thead><tr><th>Field</th><th class="num">Predicted</th><th class="num">Matched GT</th>
        <th class="num">Verified in doc</th><th class="num">True items</th><th class="num">Hallucinated</th>
        <th class="num">Verified precision</th><th class="num">Hallucination rate</th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>
    <div class="note"><strong>How to read it:</strong> every predicted item must match a ground-truth
      label OR be grounded in the document text (token coverage ≥ 0.7; dates parsed from the document).
      <strong>Matched GT</strong> = items hitting a label; <strong>Verified in doc</strong> = items grounded
      in the source; <strong>True items</strong> = either; <strong>Hallucinated</strong> = neither —
      these drive the row's hallucination rate and verified precision.</div>`);
}

function extractionScoresSection(ex, opts = {}) {
  const parts = [];
  const metrics = {
    "overall score": ex.overall_score,
    "field presence": ex.field_presence,
    "schema valid": ex.schema_valid,
  };
  if (opts.verified !== false) metrics["verified precision (factuality)"] = ex.overall_verified_precision;
  if (opts.category !== false) metrics["category presence (CUAD coverage)"] = ex.category_presence;
  const meaning = {
    "overall score": "mean of the per-field content scores over expected fields with a non-null ground-truth value",
    "field presence": "share of expected fields the model populated at all (non-null/non-empty)",
    "schema valid": "output parsed as conformant JSON — 0 means the row was unusable",
    "verified precision (factuality)": "share of predicted items that match a ground-truth label OR are grounded in the document text",
    "category presence (CUAD coverage)": "share of the document's applicable CUAD presence-categories whose clause text appears in the extraction",
  };
  const rows = Object.entries(metrics)
    .filter(([, v]) => v !== undefined)
    .map(([k, v]) => `<div class="score-row"><div class="name" title="${esc(meaning[k] || "")}">${esc(k)}</div>
      <div class="track"><i class="${band(v)?.cls ?? ""}" style="width:${v == null ? 0 : (Math.max(0, Math.min(1, v)) * 100).toFixed(1)}%"></i></div>
      <div class="value">${v == null ? "—" : fmt.pct(v)}</div></div>`)
    .join("");
  parts.push(`<div style="max-width:640px">${rows}</div>`);
  if (ex.field_scores && Object.keys(ex.field_scores).length) {
    parts.push(`<div style="margin-top:10px"><strong class="soft" style="font-size:12px">Per-field content scores</strong>
      <div style="max-width:640px">${scoreRows(ex.field_scores)}</div></div>`);
  }
  parts.push(`<div class="note"><strong>How these are scored:</strong> ${EXTRACTION_INTERPRETATION}</div>`);
  return kvCard("Extraction scores — interpreted", parts.join(""));
}

function predictedExtractionCard(pred) {
  if (!pred || typeof pred !== "object") return "";
  const rows = Object.entries(pred)
    .filter(([, v]) => v !== null && v !== undefined && v !== "")
    .map(([k, v]) => {
      const html = Array.isArray(v)
        ? v.map((x) => `<div class="mono" style="padding:2px 0">• ${esc(x)}</div>`).join("")
        : `<span class="mono">${esc(v)}</span>`;
      return `<tr><td class="k">${esc(k)}</td><td class="v">${html}</td></tr>`;
    })
    .join("");
  return kvCard("Predicted extraction (model output)", `<table class="kv">${rows}</table>`);
}

async function renderDoc(runId, docIndex) {
  const run = await fetchJson(`data/runs/${String(runId).padStart(3, "0")}.json`);
  const res = (run.results || [])[docIndex];
  if (!res) {
    $("#view").innerHTML = `<div class="empty">Document ${docIndex} not found in run #${runId}.</div>`;
    return;
  }
  const task = run.task;
  const total = run.results.length;
  const sorter = res.sorter || {};
  const sections = [];

  /* Stage 1 — classification (subtype and chained runs). */
  if (task === "subtype_classification" || task === "chained_sorter_extractor") {
    sections.push(kvCard("Sorter classification", `
      <div class="kv" style="max-width:720px">${kvRowsTyped({
        "doc type": sorter.doc_type,
        "contract subtype": sorter.contract_subtype,
        "expected subtype": sorter.expected_subtype,
        "doc type ok": sorter.doc_type_ok,
        "subtype ok": sorter.subtype_ok,
        ...(task === "subtype_classification" ? { "subtype ok (equiv)": sorter.subtype_ok_equiv } : {}),
        ...(sorter.failure_mode ? { "failure mode": sorter.failure_mode } : {}),
        confidence: sorter.confidence,
        truncated: sorter.truncated,
      })}</div>
      <h3 style="margin:14px 0 6px;font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:var(--text-faint)">Model reasoning</h3>
      <pre class="trace-reasoning">${esc(sorter.reasoning || "(no reasoning recorded)")}</pre>`));
    sections.push(kvCard("Sorter tokens", `<table class="kv">${kvRowsTyped(res.sorter_tokens)}</table>`));
  }

  /* Stage 2 — extraction scores, interpreted, where applicable. */
  if (task === "contract_entity_extraction") {
    sections.push(extractionScoresSection(res, { verified: false, category: false }));
    sections.push(entityAuditTable(res.entity_list_audit));
    if (res.entity_list_f1 && Object.keys(res.entity_list_f1).length) {
      sections.push(kvCard("Entity-list scores (raw audit)", `<table class="kv">${kvRowsTyped(res.entity_list_f1)}</table>`));
    }
    if (res.ambiguous_fields?.length) {
      sections.push(kvCard("Ambiguous fields", `<span class="mono">${esc(res.ambiguous_fields.join(", "))}</span>
        <div class="note">Scores inside the ambiguous band [0.5, 0.85] — these fields trigger the optional judge review pass (SCORING.md §3).</div>`));
    }
    sections.push(kvCard("Tokens", `<table class="kv">${kvRowsTyped(res.tokens)}</table>`));
  }

  if (task === "chained_sorter_extractor") {
    const ex = res.extractor_scores || {};
    sections.push(extractionScoresSection(ex));
    sections.push(entityAuditTable(ex.entity_list_audit));
    if (ex.entity_list_f1 && Object.keys(ex.entity_list_f1).length) {
      sections.push(kvCard("Entity-list scores (raw audit)", `<table class="kv">${kvRowsTyped(ex.entity_list_f1)}</table>`));
    }
    if (ex.category_presence_detail && Object.keys(ex.category_presence_detail).length) {
      const applicable = Object.entries(ex.category_presence_detail).filter(([, c]) => c.expected === true);
      if (applicable.length) {
        sections.push(kvCard("CUAD category presence", `
          <div class="table-wrap"><table class="data">
            <thead><tr><th>Category</th><th>Matched</th><th>Field</th></tr></thead>
            <tbody>${applicable.map(([cat, c]) => `<tr>
              <td class="mono">${esc(cat)}</td>
              <td>${c.matched === true ? '<span class="badge" style="color:var(--good)">covered</span>'
                    : c.matched === false ? '<span class="badge" style="color:var(--bad)">missing</span>'
                    : '<span class="faint">—</span>'}</td>
              <td class="mono">${esc(c.field || "")}</td></tr>`).join("")}</tbody>
          </table></div>
          <div class="note">Applicable CUAD presence categories (expected=true) and whether the extraction covers them (SCORING.md §4, category_presence).</div>`));
      }
    }
    if (ex.ambiguous_fields?.length) {
      sections.push(kvCard("Ambiguous fields", `<span class="mono">${esc(ex.ambiguous_fields.join(", "))}</span>
        <div class="note">Scores inside the ambiguous band [0.5, 0.85] — these fields trigger the optional judge review pass (SCORING.md §3).</div>`));
    }
    sections.push(predictedExtractionCard(ex.predicted));
    sections.push(kvCard("Extractor tokens", `<table class="kv">${kvRowsTyped(res.extractor_tokens)}</table>`));
  }

  if (res.error) {
    sections.push(kvCard("Error", `<div class="reasoning">${esc(res.error)}</div>`));
  }

  const prev = docIndex > 0 ? `<a class="trace-nav" href="#/run/${runId}/doc/${docIndex - 1}">← previous</a>` : "";
  const next = docIndex < total - 1 ? `<a class="trace-nav" href="#/run/${runId}/doc/${docIndex + 1}">next →</a>` : "";

  $("#view").innerHTML = `
    <a class="back" href="#/run/${runId}">← Run ${runId}: <span class="mono">${esc(run.experiment_name)}</span></a>
    <div class="detail-head">
      <h2 class="mono" style="font-size:16px">${esc(res.filename || "(unnamed document)")}</h2>
      <div class="meta-line">${taskTag(task, true)} · document ${docIndex + 1} of ${total}
        · ${res.status === "completed" ? '<span class="badge" style="color:var(--good)">ok</span>' : `<span class="badge" style="color:var(--bad)">${esc(res.status)}</span>`}
        <span class="trace-nav" style="float:right">${prev} ${next}</span></div>
    </div>
    ${sections.join("")}`;
  window.scrollTo(0, 0);
}

/* ---------- issue #1: prompt diff viewer ---------- */

function lineDiff(aText, bText) {
  /* Classic LCS line diff — returns rows of {kind: add|del|same, a, b}. */
  const a = aText.split("\n"), b = bText.split("\n");
  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  const rows = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) { rows.push({ kind: "same", a: a[i], b: b[j] }); i++; j++; }
    else if (dp[i + 1][j] >= dp[i][j + 1]) { rows.push({ kind: "del", a: a[i] }); i++; }
    else { rows.push({ kind: "add", b: b[j] }); j++; }
  }
  while (i < a.length) { rows.push({ kind: "del", a: a[i] }); i++; }
  while (j < b.length) { rows.push({ kind: "add", b: b[j] }); j++; }
  return rows;
}

function promptDiffHtml(aVer, bVer, prompts) {
  if (!aVer || !bVer || aVer === bVer) return "";
  const rows = lineDiff(prompts[aVer] || "", prompts[bVer] || "");
  const MAX = 4000;
  const visible = rows.length > MAX ? rows.slice(0, MAX) : rows;
  const body = visible
    .map((r) => {
      const no = r.kind === "del" ? "-" : r.kind === "add" ? "+" : " ";
      const text = r.kind === "del" ? r.a : r.b;
      return `<div class="diff-line ${r.kind}"><span class="diff-mark">${no}</span><span class="diff-text">${esc(text || " ")}</span></div>`;
    })
    .join("");
  return `<div class="diff">${body}
    ${rows.length > MAX ? `<div class="faint" style="padding:6px">… ${rows.length - MAX} more lines not shown</div>` : ""}</div>`;
}

function promptScoreDelta(aVer, bVer) {
  /* Best headline per prompt version + same-surface note. */
  const pick = (v) => {
    const rs = state.index.filter((r) => r.prompts === v && r.headline?.value != null);
    if (!rs.length) return null;
    return rs.sort((x, y) => y.headline.value - x.headline.value)[0];
  };
  const ra = pick(aVer), rb = pick(bVer);
  if (!ra || !rb) return "";
  const same = ra.sample_key === rb.sample_key;
  const d = (rb.headline.value - ra.headline.value) * 100;
  const cls = !same ? "ns" : Math.abs(d) < 1.96 * (pooledSEpp(ra, rb) || 0) ? "ns" : d > 0 ? "up" : "down";
  return `<div class="note">Best run with <b>${esc(aVer)}</b>: <a href="#/run/${ra.id}">#${ra.id}</a> ${fmt.pct(ra.headline.value)}
    · best with <b>${esc(bVer)}</b>: <a href="#/run/${rb.id}">#${rb.id}</a> ${fmt.pct(rb.headline.value)}
    → Δ ${d >= 0 ? "+" : ""}${d.toFixed(1)}pp
    <span class="delta ${cls}">${same ? (Math.abs(d) < 1.96 * (pooledSEpp(ra, rb) || 0) ? "not significant" : "significant") : "different sample surfaces — not comparable"}</span>
    <span class="faint" style="font-size:11px">(${esc(ra.sample_key)})</span></div>`;
}

async function renderPrompts() {
  if (!state.prompts) {
    state.prompts = await fetchJson("data/prompts.json");
  }
  const versions = Object.keys(state.prompts).sort();
  const pair = state.promptPair || [versions[0], versions[1]];
  $("#view").innerHTML = `
    <a class="back" href="#/">← All runs</a>
    <div class="detail-head"><h2>Prompt diff viewer</h2>
      <div class="meta-line">side-by-side what changed between two prompt versions — and what it bought you</div></div>
    <div class="card">
      <div class="filters">
        <label class="soft">A: <select id="pd-a">${versions.map((v) => `<option ${v === pair[0] ? "selected" : ""}>${esc(v)}</option>`).join("")}</select></label>
        <label class="soft">B: <select id="pd-b">${versions.map((v) => `<option ${v === pair[1] ? "selected" : ""}>${esc(v)}</option>`).join("")}</select></label>
      </div>
      <div id="pd-delta"></div>
      <div id="pd-diff"></div>
    </div>`;
  const render = () => {
    const a = $("#pd-a").value, b = $("#pd-b").value;
    state.promptPair = [a, b];
    $("#pd-delta").innerHTML = promptScoreDelta(a, b);
    $("#pd-diff").innerHTML = promptDiffHtml(a, b, state.prompts);
  };
  $("#pd-a").addEventListener("change", render);
  $("#pd-b").addEventListener("change", render);
  render();
  window.scrollTo(0, 0);
}

/* ---------- issue #1: SVG charts (trend / scatter / failure-mode stacks) ----------
 * Legibility rules (issue #1 polish):
 *  - curated palette + dash patterns so overlapping prompt series stay
 *    distinguishable (no hue-rotation collisions);
 *  - Catmull-Rom smoothing on trend lines (raw points still drawn as dots);
 *  - log-scale x axis for cost (runs span ~4 orders of magnitude — a linear
 *    axis piles every point on the y axis);
 *  - every point is hover-inspectable (tooltip panel) and click-navigates to
 *    the coordinated run (data-run-id + chartOpenRun).
 */

const CHART_PALETTE = [
  "#7d97b5", "#d9a866", "#5f9e6e", "#e26863", "#8f7dd9",
  "#4fb3b3", "#d98a5f", "#7fae4f", "#c96bd6", "#5f9ea8",
];
const CHART_DASHES = [null, "5 3", "1.5 3", "9 3 3 3", "3 3 1 3"];

function chartColor(prompt, index) {
  /* Stable per-prompt color from the curated palette (hash-based index). */
  let h = 0;
  for (const c of prompt) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  return CHART_PALETTE[h % CHART_PALETTE.length];
}

/* Points -> smooth SVG path (Catmull-Rom to cubic bezier). Keeps the line
 * legible across few, noisy runs; the raw dots remain on top. */
function smoothPath(pts, px, py) {
  if (pts.length < 3) {
    return `M ${pts.map((p) => `${px(p.x).toFixed(1)} ${py(p.y).toFixed(1)}`).join(" L ")}`;
  }
  let d = `M ${px(pts[0].x).toFixed(1)} ${py(pts[0].y).toFixed(1)}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)];
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const p3 = pts[Math.min(pts.length - 1, i + 2)];
    const c1x = p1.x + (p2.x - p0.x) / 6;
    const c1y = p1.y + (p2.y - p0.y) / 6;
    const c2x = p2.x - (p3.x - p1.x) / 6;
    const c2y = p2.y - (p3.y - p1.y) / 6;
    d += ` C ${px(c1x).toFixed(1)} ${py(c1y).toFixed(1)} ${px(c2x).toFixed(1)} ${py(c2y).toFixed(1)} ${px(p2.x).toFixed(1)} ${py(p2.y).toFixed(1)}`;
  }
  return d;
}

/* Runs are the inspection unit on every chart: keep their detail handy for
 * the hover tooltip + click navigation. */
const CHART_RUNS = {};

function chartRunTip(runId) {
  const e = CHART_RUNS[runId];
  if (!e) return "";
  const cost = (typeof e.cost_total_usd === "number" && e.cost_total_usd > 0)
    ? `<b>$${e.cost_total_usd.toFixed(4)}</b> billed`
    : (e.cost_estimated_usd != null ? `<b>$${e.cost_estimated_usd.toFixed(4)}</b> est.` : "cost —");
  const headline = e.headline_value != null ? `${(e.headline_value * 100).toFixed(1)}%` : "—";
  return `<div class="chart-tip-title">${esc(e.experiment_name)}</div>
    <div class="chart-tip-row">run <b>#${runId}</b> · ${esc(e.model || "")}</div>
    <div class="chart-tip-row">${esc(e.prompts || "")}</div>
    <div class="chart-tip-row">headline <b>${headline}</b> · ${cost}</div>
    <div class="chart-tip-row faint">${fmt.int(e.n_rows)} rows · ${esc(e.sample_key || "")}</div>
    <div class="chart-tip-row faint">${esc(fmt.date(e.timestamp))}</div>
    <div class="chart-tip-open">open run →</div>`;
}

function chartTooltip(evt, runId) {
  const tip = document.getElementById("chart-tip");
  if (!tip) return;
  const html = chartRunTip(runId);
  if (!html) return;
  tip.innerHTML = html;
  tip.hidden = false;
  const x = evt.clientX + 14;
  const y = evt.clientY + 10;
  tip.style.left = Math.min(x, window.innerWidth - 280) + "px";
  tip.style.top = Math.min(y, window.innerHeight - 190) + "px";
}

function chartHideTip() {
  const tip = document.getElementById("chart-tip");
  if (tip) tip.hidden = true;
}

function chartOpenRun(runId) {
  if (runId != null) window.location.hash = `#/run/${runId}`;
}

function svgChart(opts) {
  const { w = 860, h = 260, series, xLabel, yLabel, yMax = 1, logX = false, smooth = false } = opts;
  const valueOf = (p) => p.y;
  const xOf = (p) => p.x;
  const pad = { l: 54, r: 18, t: 16, b: 38 };
  const iw = w - pad.l - pad.r, ih = h - pad.t - pad.b;
  const all = series.flatMap((s) => s.points);
  let xMin = Math.min(...all.map((p) => xOf(p)));
  let xMax = Math.max(...all.map((p) => xOf(p)));
  let xTicks = [];
  let xTickLabel = (v) => fmtIntX(v);
  const fmtIntX = (v) => (Math.abs(v) >= 1000 ? fmt.tokens(v) : String(v));
  if (logX) {
    const lo = Math.pow(10, Math.floor(Math.log10(Math.max(xMin, 1e-5))));
    const hi = Math.pow(10, Math.ceil(Math.log10(Math.max(xMax, 1e-4))));
    xMin = lo; xMax = hi;
    for (let v = lo; v <= hi * 1.001; v *= 10) xTicks.push(v);
    xTickLabel = (v) => (v >= 1 ? `$${v}` : `$${v.toFixed(v < 0.001 ? 4 : 3)}`);
  } else {
    const step = Math.max(1, Math.ceil(xMax / 6));
    for (let v = 0; v <= xMax + 1e-9; v += step) xTicks.push(v);
  }
  const px = (x) => logX
    ? pad.l + ((Math.log10(Math.max(x, 1e-9)) - Math.log10(xMin)) / (Math.log10(xMax) - Math.log10(xMin))) * iw
    : pad.l + ((x - xMin) / Math.max(1, xMax - xMin)) * iw;
  const py = (y) => pad.t + (1 - Math.min(1, Math.max(0, y)) / yMax) * ih;

  const gridY = [0, 0.25, 0.5, 0.75, 1]
    .map((g) => `<line x1="${pad.l}" y1="${py(g)}" x2="${w - pad.r}" y2="${py(g)}" class="grid"/>
      <text x="${pad.l - 8}" y="${py(g) + 3}" class="axis">${(g * 100).toFixed(0)}%</text>`)
    .join("");
  const gridX = xTicks
    .map((v) => `<line x1="${px(v)}" y1="${pad.t}" x2="${px(v)}" y2="${h - pad.b}" class="grid-v"/>
      <text x="${px(v)}" y="${h - pad.b + 14}" class="axis" text-anchor="middle">${esc(xTickLabel(v))}</text>`)
    .join("");

  const traces = series.map((s, si) => {
    const color = s.color || chartColor(s.label, si);
    const dash = (s.dash || CHART_DASHES[si % CHART_DASHES.length]) || undefined;
    const sorted = [...s.points].sort((a, b) => a.x - b.x);
    for (const pt of sorted) CHART_RUNS[pt.runId] = pt.run;
    const path = smooth
      ? smoothPath(sorted, px, py)
      : `M ${sorted.map((p) => `${px(p.x).toFixed(1)} ${py(p.y).toFixed(1)}`).join(" L ")}`;
    const dots = sorted.map((p) =>
      `<circle data-run-id="${p.runId}" class="dot${p.billed === false ? " est" : ""}" cx="${px(p.x).toFixed(1)}" cy="${py(p.y).toFixed(1)}" r="4" fill="${color}" stroke="${color}"></circle>`).join("");
    return `<g class="series" data-series="${esc(s.label)}" style="color:${color}">
      <path class="line" d="${path}" fill="none" stroke="${color}" stroke-width="2" ${dash ? `stroke-dasharray="${dash}"` : ""}/>
      ${dots}
    </g>`;
  }).join("");

  const swatch = (s, si) => {
    const color = s.color || chartColor(s.label, si);
    const dash = s.dash || CHART_DASHES[si % CHART_DASHES.length];
    return dash
      ? `<i style="background:repeating-linear-gradient(90deg, ${color} 0 6px, transparent 6px 9px)"></i>`
      : `<i style="background:${color}"></i>`;
  };
  const legend = series.map((s, si) =>
    `<span class="chart-legend-item" data-series="${esc(s.label)}">${swatch(s, si)}${esc(s.label)}</span>`).join("");

  return `<div class="chart">
    <svg viewBox="0 0 ${w} ${h}" class="chart-svg" role="img">
      ${gridY}
      ${gridX}
      ${traces}
      <text x="${pad.l + iw / 2}" y="${h - 8}" class="axis" text-anchor="middle">${esc(xLabel)}</text>
      <text x="10" y="${pad.t + ih / 2}" class="axis" transform="rotate(-90 10 ${pad.t + ih / 2})" text-anchor="middle">${esc(yLabel)}</text>
    </svg>
    <div class="chart-legend">${legend}</div>
    <div id="chart-tip" class="chart-tip mono" hidden></div>
  </div>`;
}

/* Event wiring for chart interaction — delegated once per chart container. */
function wireChartInteractions(container) {
  const dimOthers = (keep) => {
    container.querySelectorAll(".series").forEach((g) =>
      g.classList.toggle("dimmed", Boolean(keep) && g !== keep));
    container.querySelectorAll(".chart-legend-item").forEach((li) =>
      li.classList.toggle("dimmed", Boolean(keep) && li.dataset.series !== keep.dataset.series));
  };
  container.addEventListener("pointerover", (ev) => {
    const seriesEl = ev.target.closest(".series");
    if (seriesEl) dimOthers(seriesEl);
    const legendItem = ev.target.closest(".chart-legend-item[data-series]");
    if (legendItem) {
      const match = Array.from(container.querySelectorAll(".series"))
        .find((g) => g.dataset.series === legendItem.dataset.series) || null;
      dimOthers(match);
    }
    const node = ev.target.closest("[data-run-id]");
    if (node) chartTooltip(ev, node.dataset.runId);
  });
  container.addEventListener("pointerout", (ev) => {
    if (ev.target.closest("[data-run-id]")) chartHideTip();
    dimOthers(null);
  });
  container.addEventListener("pointerleave", () => {
    chartHideTip();
    dimOthers(null);
  });
  container.addEventListener("click", (ev) => {
    const node = ev.target.closest("[data-run-id]");
    if (node) chartOpenRun(node.dataset.runId);
  });
}

function trendChartHtml(series, task) {
  /* One smoothed line per prompt version across runs (x = run id, y = headline). */
  const groups = new Map();
  for (const e of series) {
    if (e.headline_value == null) continue;
    if (!groups.has(e.prompts)) groups.set(e.prompts, []);
    groups.get(e.prompts).push({
      x: e.id, y: e.headline_value, runId: e.id, run: e,
      tooltip: `${e.experiment_name} (run ${e.id})`,
    });
  }
  const traces = [...groups.entries()]
    .map(([prompt, points]) => ({ label: prompt, points, color: chartColor(prompt) }))
    .filter((s) => s.points.length);
  if (!traces.length) return "";
  return `<div class="card"><h2>${esc(task.replace(/_/g, " "))} — score trend across runs</h2>
    ${svgChart({ series: traces, xLabel: "run (chronological id)", yLabel: "headline score", smooth: true })}
    <div class="note">One line per prompt version, one point per run — hover a point to inspect the run, click to open it. Points on different sample surfaces (fingerprint/seed/size) are NOT directly comparable — check each run's sample key.</div>
  </div>`;
}

function scatterChartHtml(series) {
  /* Cost-vs-quality: x = total cost $ (LOG scale — runs span ~4 orders of
   * magnitude; a linear axis piles every point on the y axis), y = headline,
   * colored per prompt. Filled = billed (OpenRouter CSV), hollow = estimate. */
  const byPrompt = new Map();
  const xOf = (e) => (typeof e.cost_total_usd === "number" && e.cost_total_usd > 0)
    ? e.cost_total_usd : e.cost_estimated_usd;
  let nPoints = 0;
  series.forEach((e) => {
    const x = xOf(e);
    if (e.headline_value == null || typeof x !== "number" || x <= 0) return;
    nPoints++;
    if (!byPrompt.has(e.prompts)) byPrompt.set(e.prompts, []);
    byPrompt.get(e.prompts).push({
      x, y: e.headline_value, runId: e.id, run: e,
      billed: x === e.cost_total_usd,
      tooltip: `${e.experiment_name} — ${x === e.cost_total_usd
        ? `billed $${e.cost_total_usd.toFixed(4)}` : `est. $${e.cost_estimated_usd.toFixed(4)}`}`,
    });
  });
  if (nPoints < 2) return "";
  const traces = [...byPrompt.entries()].map(([prompt, pts]) => ({ label: prompt, points: pts, color: chartColor(prompt) }));
  return `<div class="card"><h2>Cost vs quality</h2>
    ${svgChart({ series: traces, xLabel: "total cost (USD, log scale)", yLabel: "headline score", logX: true })}
    <div class="note">Each point is one run: score against cost. Filled = billed OpenRouter totals (activity-log CSV); hollow = deterministic token × price estimate. Hover to inspect, click to open the run.</div>
  </div>`;
}

function failureModeBarsHtml(series) {
  /* Subtype runs only: stacked bars of failure_mode counts across runs. */
  const MODES = ["function_over_form", "other_fallback", "equivalent_family", "family_confusion"];
  const rows = series
    .filter((e) => e.mode_counts && Object.keys(e.mode_counts).length)
    .map((e) => ({ label: `${e.prompts} · run ${e.id}`, e }));
  if (!rows.length) return "";
  const MODE_COLORS = { function_over_form: "#d9a866", other_fallback: "#659099", equivalent_family: "#8fd0a0", family_confusion: "#e26863" };
  const maxTotal = Math.max(1, ...rows.map((r) => Object.values(r.e.mode_counts).reduce((a, b) => a + (b || 0), 0)));
  const bars = rows.map((r) => {
    const total = Object.values(r.e.mode_counts).reduce((a, b) => a + (b || 0), 0);
    const segs = MODES.filter((m) => (r.e.mode_counts[m] || 0) > 0)
      .map((m) => `<div class="stack-seg" style="width:${((r.e.mode_counts[m] / maxTotal) * 100).toFixed(1)}%;background:${MODE_COLORS[m]}" title="${esc(m)}: ${r.e.mode_counts[m]}"></div>`)
      .join("");
    return `<div class="stack-row" data-run-id="${r.e.id}"><span class="stack-label">${esc(r.label)}</span>
      <span class="stack-track"><span class="stack-fill">${segs}</span></span>
      <span class="stack-num">${total}</span></div>`;
  }).join("");
  const legend = MODES.map((m) => `<span class="chart-legend-item"><i style="background:${MODE_COLORS[m]}"></i>${esc(m)}</span>`).join("");
  return `<div class="card"><h2>Failure-mode stacked bars</h2>
    <div class="stack">${bars}</div>
    <div class="chart-legend">${legend}</div>
    <div class="note">Trend of how sorter failures break down (function_over_form / other_fallback / equivalent_family / family_confusion) — did a prompt version actually shrink <i>family_confusion</i> specifically? Click a row to open its run.</div>
  </div>`;
}

/* ---------- navigation: task links grouped under one dropdown ---------- */

function renderNav(meta) {
  /* Task links are GROUPED under a single "tasks" dropdown so the nav bar
   * never repeats per-task names; the menu is populated from the live
   * meta.tasks set (new tasks appear automatically, nothing rots). */
  const nav = document.querySelector(".nav");
  if (!nav) return;
  let group = document.getElementById("nav-tasks");
  if (!group) {
    group = document.createElement("span");
    group.id = "nav-tasks";
    group.className = "nav-group";
    group.innerHTML = `<a href="#/" class="nav-group-trigger" data-nav-stop>tasks <span class="nav-caret">▾</span></a>
      <div class="nav-group-menu"></div>`;
    const repoLink = nav.querySelector('a[href^="https://github.com"]');
    nav.insertBefore(group, repoLink);
  }
  const menu = group.querySelector(".nav-group-menu");
  menu.innerHTML = Object.keys(meta.tasks || {}).sort()
    .map((task) => `<a href="#/task/${encodeURIComponent(task)}" data-nav-stop>${esc(task.replace(/_/g, " "))}</a>`)
    .join("");
  const trigger = group.querySelector(".nav-group-trigger");
  const close = () => group.classList.remove("open");
  trigger.addEventListener("click", (ev) => {
    ev.preventDefault();
    ev.stopPropagation();
    group.classList.toggle("open");
  });
  menu.addEventListener("click", () => close());
  document.addEventListener("click", (ev) => {
    if (!ev.target.closest("#nav-tasks")) close();
  });
}

/* ---------- openrouter benchmarks view ---------- */

/* OpenRouter pricing may arrive as $/1M strings ("$0.03") or per-token
 * decimals ("0.0000055") — format both honestly. */
function fmtPrice(v) {
  if (v == null) return "—";
  const n = Number(String(v).replace(/[^0-9.+-]/g, ""));
  if (isNaN(n)) return esc(v);
  if (String(v).includes("$") || n >= 1) return `$${n}/1M`;
  return `$${n.toExponential(2)}/token`;
}

async function renderBenchmarks() {
  if (!state.benchmarks) {
    try { state.benchmarks = await fetchJson("data/benchmarks.json"); }
    catch (e) { state.benchmarks = { available: false, error: "benchmarks.json not built", data: [], meta: {} }; }
  }
  const b = state.benchmarks;
  const meta = b.meta || {};
  if (!b.available) {
    $("#view").innerHTML = `
      <a class="back" href="#/">← All runs</a>
      <div class="detail-head"><h2>OpenRouter benchmarks</h2>
        <div class="meta-line">model-selection evidence — Artificial Analysis + Design Arena</div></div>
      <div class="card"><div class="body">
        <div class="empty">Benchmarks are unavailable.<br>
          <span class="soft">${esc(b.error || "no data")}</span></div>
        <div class="note">Rebuild with a valid key:
          <span class="mono">python scripts/site/build_site.py --benchmarks-key $OPENROUTER_API_KEY</span>
          (or export <span class="mono">OPENROUTER_API_KEY</span> and rebuild).</div>
      </div></div>`;
    return;
  }
  const rows = b.data || [];
  const aa = rows.filter((r) => r.source === "artificial-analysis");
  const da = rows.filter((r) => r.source === "design-arena");
  const state2 = { source: "all", task: "intelligence", q: "" };

  const render = () => {
    let aaFiltered = aa;
    let daFiltered = da;
    if (state2.q) {
      const q = state2.q.toLowerCase();
      aaFiltered = aaFiltered.filter((r) =>
        (r.display_name + " " + r.model_permaslug).toLowerCase().includes(q));
      daFiltered = daFiltered.filter((r) =>
        (r.display_name + " " + (r.category || "")).toLowerCase().includes(q));
    }
    let html = `<a class="back" href="#/">← All runs</a>
      <div class="detail-head"><h2>OpenRouter benchmarks</h2>
        <div class="meta-line">model-selection evidence — Artificial Analysis + Design Arena ·
          <span class="faint">as of ${esc(meta.as_of || "?")}</span></div></div>
      <div class="filters">
        <input type="search" id="bm-q" placeholder="Search models / categories…" value="${esc(state2.q)}" />
        <select id="bm-source">
          <option value="all"${state2.source === "all" ? " selected" : ""}>all sources</option>
          <option value="aa"${state2.source === "aa" ? " selected" : ""}>artificial-analysis</option>
          <option value="da"${state2.source === "da" ? " selected" : ""}>design-arena</option>
        </select>
        <select id="bm-task">
          <option value="intelligence"${state2.task === "intelligence" ? " selected" : ""}>intelligence index</option>
          <option value="coding"${state2.task === "coding" ? " selected" : ""}>coding index</option>
          <option value="agentic"${state2.task === "agentic" ? " selected" : ""}>agentic index</option>
        </select>
        <span class="count">${aaFiltered.length} AA · ${daFiltered.length} DA rows</span>
      </div>`;

    if (state2.source !== "da") {
      const byTask = (r) => r[`${state2.task}_index`];
      const ranked = aaFiltered.filter((r) => byTask(r) != null)
        .sort((a, b2) => byTask(b2) - byTask(a)).slice(0, 25);
      const max = Math.max(1, ...ranked.map(byTask));
      const barRows = ranked.map((r, i) => {
        const v = byTask(r);
        const price = r.pricing
          ? `<span class="faint" style="font-size:11px">${fmtPrice(r.pricing.prompt)} in · ${fmtPrice(r.pricing.completion)} out</span>` : "";
        return `<div class="bm-row"><span class="bm-rank">${i + 1}</span>
          <span class="bm-name"><b>${esc(r.display_name)}</b>
            <span class="faint mono">${esc(r.model_permaslug)}</span> ${price}</span>
          <span class="bm-track"><i style="width:${((v / max) * 100).toFixed(1)}%"></i></span>
          <span class="bm-val">${v != null ? v.toFixed(1) : "—"}</span></div>`;
      }).join("");
      html += `<div class="card"><h2>Artificial Analysis — ${esc(state2.task)} index (top 25)</h2>
        <div class="body">${barRows || '<div class="empty">No rows for this filter.</div>'}</div></div>`;
    }
    if (state2.source !== "aa") {
      const daSorted = daFiltered.filter((r) => r.elo != null)
        .sort((a, b2) => b2.elo - a.elo).slice(0, 50);
      const rowsHtml = daSorted.map((r) => {
        const ts = r.tournament_stats || {};
        return `<tr><td class="mono"><b>${esc(r.display_name)}</b>
          <div class="faint mono">${esc(r.model_permaslug)}</div></td>
          <td>${esc(r.category || "—")}</td>
          <td class="num"><b>${r.elo != null ? Math.round(r.elo) : "—"}</b></td>
          <td class="num">${r.win_rate != null ? (r.win_rate * 100).toFixed(1) + "%" : "—"}</td>
          <td class="num">${r.avg_generation_time_ms != null ? Math.round(r.avg_generation_time_ms) + " ms" : "—"}</td>
          <td class="num faint">${[ts.first_place, ts.second_place, ts.third_place, ts.fourth_place]
            .filter((v) => v != null).join(" / ") || "—"}</td></tr>`;
      }).join("");
      html += `<div class="card"><h2>Design Arena — ELO ranking</h2>
        <div class="table-wrap"><table class="data"><thead><tr>
          <th>Model</th><th>Category</th><th class="num">ELO</th><th class="num">Win rate</th>
          <th class="num">Avg gen time</th><th class="num">1st/2nd/3rd/4th</th>
        </tr></thead><tbody>${rowsHtml || '<tr><td colspan="6"><div class="empty">No rows for this filter.</div></td></tr>'}</tbody></table></div></div>`;
    }
    html += `<div class="card"><div class="body"><div class="note">
      <b>Treat benchmark rows as evidence, not proof of availability.</b> Benchmark
      <span class="mono">model_permaslug</span> values can differ from routable model ids —
      before adopting a leader, verify it in the OpenRouter models API (pricing, context,
      provider endpoints, uptime). Source: ${esc(meta.source_url || "OpenRouter Benchmarks API")} ·
      citation: ${esc(meta.citation || "—")}.</div>
      <div class="note faint">The models this pipeline already evaluates: qwen/qwen3.7-flash,
      deepseek/deepseek-v4-flash, deepseek/deepseek-v4-pro — benchmarks here let you compare
      candidates on the same evidence before running the eval loop.</div>
    </div></div>`;
    $("#view").innerHTML = html;
    const qEl = document.getElementById("bm-q");
    const srcEl = document.getElementById("bm-source");
    const taskEl = document.getElementById("bm-task");
    const apply = () => {
      state2.q = qEl.value;
      state2.source = srcEl.value;
      state2.task = taskEl.value;
      render();
    };
    qEl.addEventListener("input", apply);
    srcEl.addEventListener("change", apply);
    taskEl.addEventListener("change", apply);
  };
  render();
  window.scrollTo(0, 0);
}

/* ---------- research memos view ---------- */

/* Minimal markdown renderer for the memo subset (headings, bold/italic,
 * inline code, links, tables, lists, blockquotes, hr). Input is escaped
 * first, then structured transforms apply. */
function renderMd(src) {
  const escMd = (s) => esc(s)
    .replace(/^\s*#+\s+(.*)$/gm, (m, h) => {
      const level = Math.min(6, (m.match(/^#+/) || [""])[0].length);
      return `</p><h${level} class="memo-h${level}">${h}</h${level}><p>`;
    })
    .replace(/^---\s*$/gm, '</p><hr class="memo-hr"><p>');
  let html = `<div class="memo-body">${escMd(src)}</div>`;
  html = html.replace(/^\s*\|.*\|\s*$/gm, (tbl) => {
    const rows = tbl.split("\n").filter((l) => l.trim().startsWith("|"));
    const cell = (c) => c.trim().replace(/^\|/, "").replace(/\|$/, "").trim();
    const split = (r) => r.split("|").slice(1, -1).map((c) => cell(c));
    const head = split(rows[0]);
    const isSep = (r) => /^\|\s*:?-{3,}/.test(r.trim());
    const body = rows.slice(2).filter((r) => !isSep(r));
    const tr = (cells, tag) => `<tr>${cells.map((c) => `<${tag}>${c}</${tag}>`).join("")}</tr>`;
    return `<table class="data memo-tbl"><thead>${tr(head, "th")}</thead><tbody>${
      body.map((r) => tr(split(r), "td")).join("")}</tbody></table>`;
  });
  const block = (lines, tag, cls) => `<${tag} class="${cls}">${lines.join("<br>")}</${tag}>`;
  const lines = html.split("\n");
  const out = [];
  let i = 0;
  while (i < lines.length) {
    const l = lines[i];
    if (/^\s*$/.test(l)) { i++; continue; }
    if (/^<h[1-6]/.test(l)) { out.push(l); i++; continue; }
    if (/^<table/.test(l)) { out.push(l); i++; continue; }
    if (/^<hr/.test(l)) { out.push(l); i++; continue; }
    const li = l.match(/^\s*(?:[-*]|\d+\.)\s+(.*)$/);
    if (li) {
      const items = [li[1]];
      while (i + 1 < lines.length && /^\s*(?:[-*]|\d+\.)\s+/.test(lines[i + 1])) { items.push(lines[i + 1].replace(/^\s*(?:[-*]|\d+\.)\s+/, "")); i++; }
      out.push(`<ul class="memo-ul">${items.map((x) => `<li>${x}</li>`).join("")}</ul>`);
      i++;
      continue;
    }
    const quote = l.match(/^>\s*(.*)$/);
    if (quote) {
      const qs = [quote[1]];
      while (i + 1 < lines.length && /^>\s*/.test(lines[i + 1])) { qs.push(lines[i + 1].replace(/^>\s*/, "")); i++; }
      out.push(block(qs, "blockquote", "memo-quote"));
      i++;
      continue;
    }
    const para = [l];
    while (i + 1 < lines.length && lines[i + 1].trim() && !/^<h[1-6]/.test(lines[i + 1]) && !/^<table/.test(lines[i + 1]) && !/^\s*(?:[-*]|\d+\.)\s+/.test(lines[i + 1]) && !/^>\s*/.test(lines[i + 1])) { para.push(lines[i + 1]); i++; }
    out.push(`<p>${para.join(" ")}</p>`);
    i++;
  }
  // Inline pass (content is already HTML-escaped): links first, then code,
  // then bold, then italic — so `**bold**`, *emphasis*, `code`, and
  // [links](target) actually render instead of leaking literal markers.
  const inline = out.join("\n")
    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (m, label, href) => {
      if (/^(https?:|\/)/.test(href)) {
        return `<a href="${href}" target="_blank" rel="noopener">${label}</a>`;
      }
      if (/^[\w.-]+\.md$/.test(href)) {
        return `<a href="#" class="memo-link" data-memo="${esc(href)}">${label}</a>`;
      }
      return `<a href="${href}">${label}</a>`;
    })
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/(^|[^*])\*([^*]+)\*(?![*])/g, "$1<em>$2</em>");
  return `<div class="memo">${inline}</div>`;
}

async function renderMemos() {
  if (!state.memos) {
    try { state.memos = await fetchJson("data/memos.json"); }
    catch (e) { state.memos = { memos: [] }; }
  }
  const memos = state.memos.memos || [];
  if (!memos.length) {
    $("#view").innerHTML = `<a class="back" href="#/">← All runs</a>
      <div class="detail-head"><h2>Research memos</h2>
        <div class="meta-line">archive of experimental findings</div></div>
      <div class="card"><div class="body"><div class="empty">No memos shipped yet — run
        <span class="mono">python scripts/site/build_site.py</span> after adding memos/*.md.</div></div></div>`;
    return;
  }
  const pair = state.memoPair || [memos[0].file, memos.length > 1 ? memos[1].file : memos[0].file];
  $("#view").innerHTML = `
    <a class="back" href="#/">← All runs</a>
    <div class="detail-head"><h2>Research memos</h2>
      <div class="meta-line">key findings from experimental runs and prompt iterations — archived for collaborators and presentation</div></div>
    <div class="card">
      <div class="filters">
        <label class="soft">Memo: <select id="mm-a">${memos.map((m) => `<option ${m.file === pair[0] ? "selected" : ""} value="${esc(m.file)}">${esc(m.title)}</option>`).join("")}</select></label>
      </div>
      <div class="body" id="mm-body"></div>
    </div>`;
  const render = () => {
    const file = document.getElementById("mm-a").value;
    state.memoPair = [file, file];
    const memo = memos.find((m) => m.file === file);
    document.getElementById("mm-body").innerHTML = memo ? renderMd(memo.markdown) : '<div class="empty">memo not found</div>';
    document.querySelectorAll(".memo-link").forEach((a) => {
      a.addEventListener("click", (ev) => {
        ev.preventDefault();
        const target = a.dataset.memo;
        const sel = document.getElementById("mm-a");
        if (sel && memos.some((m) => m.file === target)) {
          sel.value = target;
          render();
        }
      });
    });
  };
  document.getElementById("mm-a").addEventListener("change", render);
  render();
  window.scrollTo(0, 0);
}

/* ---------- boot ---------- */

async function boot() {
  try {
    initTheme();
    const [meta, index] = await Promise.all([
      fetchJson("data/meta.json"),
      fetchJson("data/index.json"),
    ]);
    state.meta = meta;
    state.index = index;
    const built = new Date(meta.built_at).toISOString().replace("T", " ").slice(0, 16);
    $("#build-time").textContent = `generated ${built} UTC from ${meta.source} · `;
    renderNav(meta);
    window.addEventListener("hashchange", route);
    await route();
  } catch (err) {
    $("#view").innerHTML =
      `<div class="empty">Could not load experiment data (${esc(err.message)}).<br>
       Regenerate with <span class="mono">python scripts/site/build_site.py</span>.</div>`;
  }
}

document.addEventListener("DOMContentLoaded", boot);
